from __future__ import annotations

import json
import re
from pathlib import Path

from .scanner import FastFlagResult, OffsetResult


def _cpp_identifier(value: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9_]", "_", value)
    if not cleaned or cleaned[0].isdigit():
        cleaned = "_" + cleaned
    return cleaned


def write_fflags_header(path: Path, flags: list[FastFlagResult], identity: str) -> None:
    lines = [
        "// Generated by Masterstrap Roblox iOS Dumper.",
        f"// Binary identity: {identity}",
        "// Values are RVAs relative to the Mach-O __TEXT image base.",
        "#pragma once",
        "#include <cstdint>",
        "",
        "namespace RobloxIOS::FFlags {",
    ]
    for flag in flags:
        lines.append(
            f"    inline constexpr std::uintptr_t {_cpp_identifier(flag.name)} = "
            f"0x{flag.rva:X}; // {flag.confidence}, {flag.segment}"
        )
    lines.extend(["}", ""])
    path.write_text("\n".join(lines), encoding="utf-8")


def write_fflags_map_header(
    path: Path, flags: list[FastFlagResult], identity: str, version_tag: str = "27351135IOS"
) -> None:
    seen: dict[str, FastFlagResult] = {}
    for f in flags:
        if f.name and f.name not in seen:
            seen[f.name] = f

    sorted_entries = sorted(seen.items(), key=lambda item: item[0])
    lines = [
        "// Generated by Masterstrap Roblox iOS Dumper.",
        f"// Binary identity: {identity}",
        "// Keys retain the complete typed name; no prefix-stripping collisions.",
        "#pragma once",
        "#include <algorithm>",
        "#include <cstdint>",
        "#include <iterator>",
        "#include <string_view>",
        "",
        f"namespace FFlags{version_tag} {{",
        "struct FFlagOffset {",
        "    std::string_view name;",
        "    uintptr_t offset;",
        "    std::string_view storage_kind;",
        "    std::string_view confidence;",
        "};",
        "",
        f"constexpr FFlagOffset g_fflagOffsets_{version_tag}[] = {{",
    ]
    kind_by_prefix = {
        "FFlag": "bool",
        "DFFlag": "bool",
        "SFFlag": "bool",
        "FInt": "int32",
        "DFInt": "int32",
        "SFInt": "int32",
        "FString": "pointer64",
        "DFString": "pointer64",
        "SFString": "pointer64",
    }
    for name, flag in sorted_entries:
        kind = kind_by_prefix.get(flag.prefix, "unknown")
        lines.append(
            f'    {{"{name}", 0x{flag.rva:X}, "{kind}", "{flag.confidence}"}},'
        )
    lines.extend([
        "};",
        "",
        "inline uintptr_t getFFlagOffset(std::string_view full_name) {",
        f"    const auto* first = std::begin(g_fflagOffsets_{version_tag});",
        f"    const auto* last = std::end(g_fflagOffsets_{version_tag});",
        "    const auto* it = std::lower_bound(first, last, full_name,",
        "        [](const FFlagOffset& entry, std::string_view wanted) {",
        "            return entry.name < wanted;",
        "        });",
        "    return it != last && it->name == full_name ? it->offset : 0;",
        "}",
        "",
        f"}} // namespace FFlags{version_tag}",
        "",
    ])
    path.write_text("\n".join(lines), encoding="utf-8")


def write_offsets_header(path: Path, offsets: list[OffsetResult], identity: str) -> None:
    lines = [
        "// Generated by Masterstrap Roblox iOS Dumper.",
        f"// Binary identity: {identity}",
        "// Only resolved candidates are emitted; inspect offsets.json evidence before use.",
        "#pragma once",
        "#include <cstdint>",
        "",
        "namespace RobloxIOS::Offsets {",
    ]
    for result in offsets:
        if result.rva is None:
            continue
        lines.append(
            f"    inline constexpr std::uintptr_t {_cpp_identifier(result.name)} = "
            f"0x{result.rva:X}; // {result.confidence}, {result.method}"
        )
    lines.extend(["}", ""])
    path.write_text("\n".join(lines), encoding="utf-8")


def write_json(path: Path, payload: object) -> None:
    path.write_text(
        json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )


def write_log(
    path: Path,
    manifest: dict[str, object],
    offsets: list[OffsetResult],
    flags: list[FastFlagResult],
    flag_scan: dict[str, object],
) -> None:
    lines = [
        "Masterstrap Roblox iOS Dumper",
        f"status={manifest['status']}",
        f"source={manifest['input']['source_path']}",
        f"binary={manifest['input']['binary_path']}",
        f"architecture={manifest['macho']['architecture']}",
        f"uuid={manifest['macho']['uuid']}",
        f"sha256={manifest['input']['sha256']}",
        f"encrypted={int(bool(manifest['macho']['encrypted']))}",
        f"image_base=0x{int(manifest['macho']['image_base']):X}",
        f"offsets_resolved={sum(item.rva is not None for item in offsets)}",
        f"offsets_missing={sum(item.rva is None for item in offsets)}",
        f"register_function={flag_scan.get('register_function')}",
        f"registration_calls={flag_scan.get('registration_calls', 0)}",
        f"fflags_decoded={len(flags)}",
        "",
        "[offsets]",
    ]
    for result in offsets:
        value = f"0x{result.rva:X}" if result.rva is not None else "missing"
        lines.append(f"{result.name}={value} confidence={result.confidence}")
    lines.extend(["", "[fflags]"])
    for flag in flags:
        lines.append(
            f"{flag.name}=0x{flag.rva:X} confidence={flag.confidence} "
            f"segment={flag.segment}"
        )
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
